import sys, json, re, hashlib, base64, datetime, difflib, fnmatch, ast

# THE READING SIDE OF A FILE SPACE (file-space, GH #899). Every read of a file
# in this space arrives here on `in_read` and leaves as exactly one `answer`:
# `info`, `read`, `search` (exact, regex), `summary`, `history`, `show`,
# `diff`, `list`, `find`, `raw`, and the node reads `outline`, `links`, `near`
# and `read` of one node (`fh-...#<anchor>`, GH #944), and `dir_info` of one
# directory (GH #947). `ask`, the semantic search and `dir_summary` go to
# `./derive`; this cell never sees them.
#
# DIRECTORIES ARE ROWS OF THEIR OWN (GH #947). `dirs` holds one row per
# directory with the counts of its subtree, kept by `./derive`; this cell only
# reads them. `subdirs` is never stored: it is counted here from the living
# rows whose `parent` is the directory. The root `/` always exists -- without
# a row it reads as a row of zeros.
#
# A FILE IS AN ADDRESS, NOT A PLACE (ADR 0047). A request names a file by its
# id (`fh-<12 hex>`) or its path, optionally pinned to a version (`@<hex>`),
# a workspace (`@ws:<name>`) or a snapshot (`@snap:<name>`). No answer field
# carries where the file lives: not the store, not the space, not the hive.
# Moving every row of a file into another space's store changes no answer.
#
# EVERY QUERY NAMES ITS FILE. The one store holds the rows of every file of
# the space; a row belongs to the file its `file` column names, and a block
# hash shared by two files is two rows. So every select on a table with a
# `file` column carries `file` in its `where` -- the only exception is
# `files` itself, for the path lookup, `list` and `find` -- and every select
# carries a `limit` (a select without one is unbounded).
#
# THIS CELL NEVER WRITES A FILE. The one table it writes is `pending`, its own
# working values between two store phases (`op`, `op_id`, `caller`, `ws` and
# the arguments do not survive a hop, and a working value never rides in
# context). A prepared commit is read as it stands -- committed: the plan's
# target, else the head -- and never recovered from here.
#
# The request: body `{op, file?, args{}}`, hop `op`, `op_id`, `ws?`, `mode?`,
# `caller?`. The answer: route `answer`, hop `op`, `op_id`, `caller` mirrored,
# body `{ok, op, op_id, file, version, ...}` or `{ok: false, op, op_id,
# error: {code, message}}`.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return int(float(v))


MAX_LINES = max(1, _int("max_lines", 2000))
MAX_CHARS = max(100, _int("max_chars", 25000))
SEARCH_LIMIT = max(1, _int("search_limit", 20))
DIFF_LINES = max(10, _int("diff_lines", 400))
# The node reads (GH #944). The caps are the extractor's own (`./derive` keeps
# the same params): an older version computed here answers like the head rows
# `./derive` wrote while it was head.
NODES_MAX = max(1, _int("nodes_max", 2000))
LINKS_MAX = max(1, _int("links_max", 5000))
NEAR_SCAN_MAX = max(1, _int("near_scan_max", 5000))
LIMITS = {"nodes_max": NODES_MAX, "links_max": LINKS_MAX,
          "extract_max_bytes": _int("extract_max_bytes", 2097152),
          "key_depth": _int("key_depth", 3)}

ME = "read"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
OPS = ("info", "read", "search", "summary", "history", "show", "diff", "list", "find", "raw",
       "outline", "links", "near", "dir_info")
# Ops that address no single file.
SPACE_OPS = ("list", "find", "dir_info")
# Ops whose answer needs the content of a version.
CONTENT_OPS = ("read", "search", "show", "diff", "raw")
PATTERN_MAX = 500
LONG_LINE = 4000
CONTEXT_MAX = 2
SHOW_LINES = 40
HISTORY_MAX = 200
BLOCK_TRANCHE = 200
PARTS_MAX = 5000
CANDIDATES_MAX = 10
LIST_SCAN = 2000
FIND_PAGE = 500
FIND_SCAN = 20000
FIND_LIMIT = 100
FIND_LIMIT_MAX = 500
ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
# Ops answered from a file's nodes and links (GH #944).
NODE_OPS = ("outline", "links")
OUTLINE_LIMIT = 200
LINKS_LIMIT = 500
NEAR_K = 5
NEAR_K_MAX = 10
ANCHOR_CANDIDATES = 5
NODE_COLS = ["anchor", "kind", "parent", "unit", "from_pos", "to_pos", "oneline", "parser"]
LINK_COLS = ["from_anchor", "kind", "target_name", "pos", "alias"]
# One order for the rows of the head (the store's `order_by`) and for a
# version computed from its blocks (`node_key`/`link_key`): source order,
# an enclosing item before what it holds, the anchor breaking a tie of two
# items on one line. The same key on both sides is what makes the outline of
# an older version the answer it gave while it was head.
NODE_ORDER = [("from_pos", "asc"), ("to_pos", "desc"), ("anchor", "asc")]
LINK_ORDER = [("pos", "asc"), ("from_anchor", "asc"), ("kind", "asc"), ("target_name", "asc"),
              ("alias", "asc")]
ANCHOR_DUP_RE = re.compile(r"~[0-9]+$")
# `dir_info` (GH #947): one page of a directory's children, by path.
