            "tomb"]


# ============================================================ THE TWINS
# `parse_addr`, `line_hash` and `text_view` recur word for word in every cell
# of this space that needs them (`script_inline` has no library); the lock
# `gh899_the_twins_parse_one_address` runs every copy against one table.

def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def line_hash(line):
    """`h4`: the first four hex digits of the sha256 of one line without its
    line ending (`\\n`, `\\r\\n`)."""
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    return hashlib.sha256(line.encode("utf-8")).hexdigest()[:4]


def text_view(content, derived):
    """The text a version reads as: its derived pages (`[{part, text}]`),
    each headed `--- page <n> ---`, when it has any, else its own lines when
    the content is UTF-8 without NUL. Pages first: an extractor made them
    because the bytes are not the text, and a PDF can be pure ASCII
    (GH #907, OR-FJ.I.22). {kind, lines, pages: {n: [from, to]}} (1-based,
    inclusive) or {error: 'no_text'}. A line keeps a `\\r` of its ending;
    `\\n` ends a line, a last line without one counts."""
    def split(t):
        if t == "":
            return []
        parts = t.split("\n")
        if t.endswith("\n"):
            parts = parts[:-1]
        return parts

    parts = sorted((p for p in (derived or []) if isinstance(p, dict)),
                   key=lambda p: int(p.get("part") or 0))
    text = None
    if not parts and isinstance(content, (bytes, bytearray)) and b"\x00" not in content:
        try:
            text = bytes(content).decode("utf-8")
        except UnicodeDecodeError:
            text = None
    if text is not None:
        return {"kind": "text", "lines": split(text), "pages": {}}
    if not parts:
        return {"error": "no_text"}
    lines, pages = [], {}
    for p in parts:
        n = int(p.get("part") or 0)
        start = len(lines) + 1
        lines.append("--- page %d ---" % n)
        lines.extend(split(str(p.get("text") or "")))
        pages[n] = [start, len(lines)]
    return {"kind": "derived", "lines": lines, "pages": pages}


# ---- directories (GH #947) -- word for word in ./write, ./derive and ./read
# A directory is a path without a trailing slash ("/" is the root): the
# directory of a file is everything before its last "/", and its ancestors
# are every prefix up to it, root first. The lock
# `gh947_the_directory_twins_are_one` runs every copy against one table.
TAGS_MAX = 8
TAG_CHARS = 32


def dir_of(path):
    """The directory a path lives in: '/a/b/x.py' -> '/a/b', '/x' -> '/'."""
    p = str(path or "").rstrip("/")
    i = p.rfind("/")
    return p[:i] if i > 0 else "/"


def dir_norm(path):
    """A directory as the rows name it: '/a/b/' -> '/a/b', '' -> '/'."""
    return "/" + "/".join(s for s in str(path or "").split("/") if s)


def ancestors(d):
    """'/a/b' -> ['/', '/a', '/a/b'] (root first); '/' -> ['/']."""
    segs = [s for s in str(d or "").split("/") if s]
    return ["/"] + ["/" + "/".join(segs[:i]) for i in range(1, len(segs) + 1)]


def dir_parent(d):
    """The parent of a directory; '' for the root."""
    d = dir_norm(d)
    return "" if d == "/" else dir_of(d)


def dir_depth(d):
    """Segments below the root: '/' -> 0, '/a/b' -> 2."""
    return len([s for s in str(d or "").split("/") if s])


def tags_norm(v):
    """A tag list as it is stored: strings, lower case, inner whitespace
    folded, cut to TAG_CHARS, no empty one, no repeat, at most TAGS_MAX (the
    first ones win). A JSON string of a list is read too; anything else is []."""
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            return []
    if not isinstance(v, list):
        return []
    out = []
    for t in v:
        if not isinstance(t, str):
            continue
        t = " ".join(t.lower().split()).strip(" .;:")[:TAG_CHARS].rstrip()
        if t and t not in out:
            out.append(t)
        if len(out) == TAGS_MAX:
            break
    return out
# ---- directories end


# ============================================================ PLUMBING

def strict_json(v):
    """`v` as JSON every strict parser takes (GH #947, ledger line 15 of wave
    C): a `\\udXXX` escape in a tool call's text survives `json.loads` as a
    lone surrogate, `json.dumps` writes it back as the same escape, and the
    colony refuses that emission -- the model never got its `tool_result`.
    A lone surrogate leaves as U+FFFD; a pair stays its one character."""
    out = json.dumps(v)
    if "\\ud" not in out:
        return out
    s = json.dumps(v, ensure_ascii=False).encode("utf-16", "surrogatepass")
    return json.dumps(json.loads(s.decode("utf-16", "replace")))


def emit(msgs):
    # OR-FJ.L.8: a body with none of `messages`/`system`/`attachments` is no
    # UBF body, and a debug colony dead-letters it without an answer
    # (`invalid_ubf_body`) -- measured in the gh908 colony lock on the
    # `in_check` of `write`. Every emission leaves with its slot.
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(strict_json(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("file-space/read: %s\n" % reason)
    emit([])


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def v12(v):
    return str(v or "")[:12]


def loads(v, default):
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            return default
    return default if v is None else v


def sel(table, columns, where, order=None, limit=1):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": int(limit)}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def store(ops, phase):
    return {"header": {"route": "read_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def one(lg, cid):
    r = rows(lg, cid)
    return r[0] if r else None


def parked_ops(S, phase, first=False):
    """The two legs every non-final bundle opens with: park the working values
    (insert on the first phase, update after), then echo them back."""
    key = {"op_id": S["op_id"], "cell": ME}
    body = json.dumps(S, sort_keys=True)
    if first:
        put = {"operation": "insert", "table": "pending",
               "row": {"op_id": S["op_id"], "cell": ME, "phase": phase, "body": body,
                       "at": now()}}
    else:
        put = {"operation": "update", "table": "pending",
               "set": {"phase": phase, "body": body}, "where": key}
    return [("p-put", put),
            ("p-echo", sel("pending", ["op_id", "body"], key, None, 1))]


def next_phase(S, phase, ops, first=False):
    emit([store(parked_ops(S, phase, first) + ops, phase)])


def finish(S, body, parked=True):
    msg = {"header": {"route": "answer", "op": S["op"], "op_id": S["op_id"],
                      "caller": S.get("caller", "")},
           "messages": [], "op": S["op"], "op_id": S["op_id"]}
    msg.update(body)
    msgs = [msg]
    if parked:
        msgs.append(store([("p-drop", {"operation": "delete", "table": "pending",
                                       "where": {"op_id": S["op_id"], "cell": ME}})],
                          "done"))
    emit(msgs)


def fail(S, code, message, parked=True, extra=None):
    err = {"code": code, "message": message}
    err.update(extra or {})
    finish(S, {"ok": False, "error": err}, parked)


def ok(S, body):
    out = {"ok": True}
    if S.get("file_id"):
        out["file"] = S["file_id"]
    out.update(body)
    finish(S, out)


# ============================================================ PURE READS

def fmt_line(n, line):
    if line.endswith("\r"):
        line = line[:-1]
    return "%d:%s|%s" % (n, line_hash(line), line)


def window(lines, a, b):
    """Lines a..b (1-based, inclusive) formatted, cut at MAX_LINES and
    MAX_CHARS; -> (text, first, last, more)."""
    total = len(lines)
    out, chars, last = [], 0, a - 1
    for n in range(a, b + 1):
        s = fmt_line(n, lines[n - 1])
        if len(out) >= MAX_LINES or (out and chars + len(s) + 1 > MAX_CHARS):
            break
        out.append(s)
        chars += len(s) + 1
        last = n
    more = None
    if last < b:
        nxt = last + 1
        more = {"from": nxt, "to": min(b, nxt + MAX_LINES - 1)}
    return "\n".join(out), a, last, more


def page_ignored(args, tv):
    """`page` picks among the real pages of a paged document only (GH #994).
    Models that fill every optional field send `{"from": 1, "page": 0,
    "to": 6}` for a source file; `page` took precedence over the range, a
    source file has no pages, and every such read answered `page_unknown` --
    every file read of two hosted models in one measured run. On a version
    without pages a `page` of 0 or 1 is therefore ignored (the range or the
    whole file is read, the answer says `ignored: ["page"]`); any other
    number there, and every number on a paged document, still pages."""
    if tv["pages"]:
        return False
    try:
        return int(args.get("page")) in (0, 1)
    except (TypeError, ValueError):
        return False


def span(args, total):
    """`from`/`to` 1-based inclusive, negative counts from the end."""
    def num(k, dflt):
        v = args.get(k)
        if v is None or v == "":
            return dflt
        return int(v)
    a = num("from", 1)
    b = num("to", 0)
    if a < 0:
        a = total + 1 + a
    if b < 0:
        b = total + 1 + b
    if b == 0:
        # No end given: to the end of the file; `window` stops at the limits
        # and `more` names the rest.
        b = total
    a = max(1, a)
    b = min(total, b)
    return a, b


def ctx_line(n, raw):
    """A context line in read form, its text cut at LONG_LINE (the hash is
    of the whole line)."""
    t = raw[:-1] if raw.endswith("\r") else raw
    return "%d:%s|%s" % (n, line_hash(t), t[:LONG_LINE])


def search_lines(lines, pattern, mode, context, limit):
    """-> (hits, total, cut): at most `limit` hits, and no more than
    MAX_CHARS of text across them (`cut` then says so)."""
    if mode == "regex":
        rx = re.compile(pattern)
        match = lambda t: rx.search(t) is not None
    else:
        match = lambda t: pattern in t
    hits, total, chars, cut = [], 0, 0, False
    for i, raw in enumerate(lines):
        t = raw[:-1] if raw.endswith("\r") else raw
        long_line = len(t) > LONG_LINE
        probe = t[:LONG_LINE] if long_line else t
        if not match(probe):
            continue
        total += 1
        if len(hits) >= limit or cut:
            continue
        n = i + 1
        hit = {"line": n, "h4": line_hash(t), "text": probe}
        if long_line:
            hit["long_line"] = True
        if context:
            hit["before"] = [ctx_line(k, lines[k - 1]) for k in range(max(1, n - context), n)]
            hit["after"] = [ctx_line(k, lines[k - 1])
                            for k in range(n + 1, min(len(lines), n + context) + 1)]
        size = len(hit["text"]) + sum(len(x) + 1 for x in hit.get("before", []) + hit.get("after", []))
        if hits and chars + size > MAX_CHARS:
            cut = True
            continue
        chars += size
        hits.append(hit)
    return hits, total, cut


def unified(a_lines, b_lines, a_name, b_name):
    a = [x + "\n" for x in a_lines]
    b = [x + "\n" for x in b_lines]
    out = [x.rstrip("\n") for x in difflib.unified_diff(a, b, a_name, b_name, n=3)]
    cut = len(out) > DIFF_LINES
    out = out[:DIFF_LINES]
    chars = 0
    for i, x in enumerate(out):
        chars += len(x) + 1
        if i and chars > MAX_CHARS:
            out, cut = out[:i], True
            break
    return "\n".join(out), cut


def history_rows(rows_, limit):
    """`line` rows newest first, a commit's line once -- its smallest `seq`:
    a recovery race can append the same commit twice (OR-FH-85)."""
    last = {}
    for i, r in enumerate(rows_):
        c = str(r.get("commit") or "")
        if c:
            last[c] = i
    out = [r for i, r in enumerate(rows_)
           if not str(r.get("commit") or "") or last[str(r.get("commit"))] == i]
    return out[:limit]


def assemble(version_row, blocks_rows):
    """The bytes of a version from its block list; None when a block is
    missing (corrupt -- never skipped)."""
    hashes = loads(version_row.get("blocks"), [])
    have = {}
    for r in blocks_rows:
        have[str(r.get("hash") or "")] = r
    parts = []
    for h in hashes:
        r = have.get(str(h))
        if r is None:
            return None
        body = str(r.get("body") or "")
        if str(r.get("enc") or "utf8") == "b64":
            try:
                parts.append(base64.b64decode(body, validate=True))
            except Exception:
                return None
        else:
            parts.append(body.encode("utf-8"))
    return b"".join(parts)


def list_entries(rows_, prefix, depth):
    """Files under `prefix` (rows ordered by path) grouped to `depth`
    segments: a file within reach is itself, a deeper one counts toward its
    directory at the cut."""
    base = prefix if prefix.endswith("/") else prefix + "/"
    files, dirs = [], {}
    for r in rows_:
        path = str(r.get("path") or "")
        if path == prefix:
            files.append(r)
            continue
        if not path.startswith(base):
            continue
        segs = path[len(base):].split("/")
        if len(segs) <= depth:
            files.append(r)
        else:
            d = base + "/".join(segs[:depth]) + "/"
            dirs[d] = dirs.get(d, 0) + 1
    out = [{"path": str(r.get("path")), "file": str(r.get("file")),
            "bytes": int(r.get("bytes") or 0), "lines": int(r.get("lines") or 0)}
           for r in files]
    out += [{"path": k, "dir": True, "files": v} for k, v in dirs.items()]
    out.sort(key=lambda e: e["path"])
    return out


# ---- directories (GH #947): the `dirs` rows as an answer carries them

def top_tags(raw, n=DIR_TAGS_TOP):
    """The `tags` counters of a `dirs` row (a JSON object `{tag: count}`) as
    `[{tag, n}]`: the `n` most frequent, a tie by tag; [] for none or an
    unreadable one."""
    got = loads(raw, {})
    if not isinstance(got, dict):
        return []
    out = []
    for t, c in got.items():
        try:
            c = int(c)
        except (TypeError, ValueError):
            continue
        if isinstance(t, str) and t and c > 0:
            out.append((-c, t))
    return [{"tag": t, "n": -c} for c, t in sorted(out)[:n]]


def nonneg(v):
    """A stored counter as the reader shows it: `derive` stores the sum of
    the deltas with its sign, so the order two syncs land in changes
    nothing; a sum below zero is drift and reads as zero (GH #973 M-1)."""
    try:
        return max(0, int(v or 0))
    except (TypeError, ValueError):
        return 0


def dir_base(path):
    return path if path.endswith("/") else path + "/"


def child_files(rs, path):
    """The files directly in `path` out of a path range read from
    `path + "/"` on (GH #973 M-2): by `path`, not `files.dir`, so a row
    written before `dir` existed is a child of its folder too, without a
    backfill. The store takes one operator per column, so the range has no
    upper end: rows past `path0` and rows deeper down are cut here."""
    base = dir_base(path)
    return [r for r in rs if str(r.get("path") or "").startswith(base)
            and "/" not in str(r.get("path") or "")[len(base):]]


def dir_counts(row):
    """The counts of a directory from its `dirs` row; a directory without one
    (the root before its first file, a directory the scan found ahead of its
    row) counts zero, is clean and has no topics."""
    row = row or {}
    return {"files": nonneg(row.get("files")), "bytes": nonneg(row.get("bytes")),
            "nodes": nonneg(row.get("nodes")), "dirty": bool(int(row.get("dirty") or 0)),
            "tags": top_tags(row.get("tags")), "summary": str(row.get("summary") or "")}


def subdir_counts(drows):
    """{directory: its living child rows} over the rows read."""
    out = {}
    for r in drows:
        if str(r.get("tomb") or ""):
            continue
        p = str(r.get("parent") or "")
        if p:
            out[p] = out.get(p, 0) + 1
    return out


def dir_entries(entries, drows, prefix, depth):
    """`list_entries` with the directories of `dirs` (GH #947): a directory
    entry carries `files`, `bytes`, `nodes`, `subdirs`, `dirty`, `tags` (its
    top topics) and `summary` (only when one is written) from its row, and a
    directory with no file in reach -- one made by `create_dir`, or emptied --
    is an entry too: at the cut, or nearer when it holds no file at all.
    Without a row, `files` stays the scan's count and the rest is zero."""
    base = prefix if prefix.endswith("/") else prefix + "/"
    pd = dir_depth(base)
    live = {}
    for r in drows:
        p = str(r.get("path") or "")
        if str(r.get("tomb") or "") or not p.startswith(base) or dir_depth(p) <= pd:
            continue
        live[p] = r
    kids = subdir_counts(drows)
    have = {e["path"] for e in entries}
    out = list(entries)
    for p, r in sorted(live.items()):
        rel = dir_depth(p) - pd
        if rel == depth or (rel < depth and not nonneg(r.get("files"))):
            if p + "/" not in have:
                out.append({"path": p + "/", "dir": True, "files": 0})
                have.add(p + "/")
    for e in out:
        if not e.get("dir"):
            continue
        p = dir_norm(e["path"])
        row = live.get(p)
        c = dir_counts(row)
        files = c["files"] if row is not None else int(e.get("files") or 0)
        summary = c.pop("summary")
        e.update(files=files, bytes=c["bytes"], nodes=c["nodes"], subdirs=kids.get(p, 0),
                 dirty=c["dirty"], tags=c["tags"])
        if summary:
            e["summary"] = summary
    out.sort(key=lambda e: e["path"])
    return out


def seq_iso(seq):
    """A `head_seq` (µs since the epoch) as the time it names; '' for none."""
    try:
        us = int(seq or 0)
    except (TypeError, ValueError):
        return ""
    if us <= 0:
        return ""
    t = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc) + \
        datetime.timedelta(microseconds=us)
    return t.strftime(FMT)


def dir_children(drows, frows, limit):
    """One page of a directory's children by path -- its living subdirectory
    rows and its living files -- and the `next` cursor ('' at the end). Each
    list is read past the cursor with `limit + 1` rows, so the first `limit`
    of the two merged are the page."""
    kids = []
    for r in drows:
        p = str(r.get("path") or "")
        kids.append({"name": p.rsplit("/", 1)[-1], "path": p, "type": "dir",
                     "files": nonneg(r.get("files")), "bytes": nonneg(r.get("bytes")),
                     "nodes": nonneg(r.get("nodes")),
                     "dirty": bool(int(r.get("dirty") or 0)),
                     "summary": str(r.get("summary") or "")})
    for r in frows:
        p = str(r.get("path") or "")
        kids.append({"name": p.rsplit("/", 1)[-1], "path": p, "type": "file",
                     "file": str(r.get("file") or ""), "kind": str(r.get("kind") or ""),
                     "mime": str(r.get("mime") or ""), "bytes": int(r.get("bytes") or 0),
                     "lines": int(r.get("lines") or 0), "version": v12(r.get("head")),
                     "changed": seq_iso(r.get("head_seq")),
                     "oneline": str(r.get("oneline") or "")})
    kids.sort(key=lambda k: k["path"])
    if len(kids) > limit:
        return kids[:limit], kids[limit - 1]["path"]
    return kids, ""


def dir_args(a):
    """`dir_info`'s arguments -> (path, cursor, limit) or an error message."""
    raw = a.get("path")
    if not isinstance(raw, str) or not raw.startswith("/") or "\x00" in raw or len(raw) > 1024:
        return "dir_info takes a path: an absolute directory"
    cur = a.get("cursor")
    if cur is None:
        cur = ""
    if not isinstance(cur, str):
        return "cursor is the `next` of the page before"
    lim = a.get("limit")
    try:
        limit = DIR_LIMIT if lim in (None, "") else int(lim)
    except (TypeError, ValueError):
        return "limit is a number"
    return dir_norm(raw), cur, max(1, min(DIR_LIMIT_MAX, limit))


# ---- node reads (GH #944): pure, the extractor block below makes the nodes

def node_of(r):
    """A node as an answer carries it, from a `nodes` row (`from_pos`) or from
    `extract` (`from`)."""
    return {"anchor": str(r.get("anchor") or ""), "kind": str(r.get("kind") or ""),
            "parent": str(r.get("parent") or ""), "unit": str(r.get("unit") or "line"),
            "from": int(r.get("from_pos", r.get("from")) or 0),
            "to": int(r.get("to_pos", r.get("to")) or 0),
            "oneline": str(r.get("oneline") or ""), "parser": str(r.get("parser") or "")}


def link_of(r):
    """One link of the answer, from a stored row or from `extract`: the
    stored row carries `alias` as '' when there is none, `extract` leaves the
    key out -- both answer without the key, so an older version answers what
    it answered as head."""
    out = {"kind": str(r.get("kind") or ""), "from_anchor": str(r.get("from_anchor") or ""),
           "target_name": str(r.get("target_name") or ""), "pos": int(r.get("pos") or 0)}
    if str(r.get("alias") or ""):
        out["alias"] = str(r.get("alias"))
    return out


def node_key(n):
    return (n["from"], -n["to"], n["anchor"])


def link_key(l):
    return (l["pos"], l["from_anchor"], l["kind"], l["target_name"], l.get("alias", ""))


def page_args(a, default, cap):
    """`cursor` (an offset as a string, '' the start) and `limit` (default,
    1..cap) -> (offset, limit); ValueError when either is not a number."""
    cur = a.get("cursor")
    cur = "" if cur is None else str(cur).strip()
    if cur and not cur.isdigit():
        raise ValueError("cursor")
    lim = a.get("limit")
    limit = default if lim in (None, "") else int(lim)
    return (int(cur) if cur else 0), max(1, min(cap, limit))


def paged(items, offset, limit):
    """One page of `items` and its `next` ('' at the end)."""
    page = items[offset:offset + limit]
    return page, (str(offset + limit) if offset + limit < len(items) else "")


def anchor_name(anchor):
    """The name an anchor ends in -- its last segment without the art, a key
    pointer's last token, without a `~n` of a duplicate, %XX decoded: what
    `unknown_anchor` matches its candidates by."""
    last = str(anchor).rsplit("/", 1)[-1]
    return pct_decode(ANCHOR_DUP_RE.sub("", last.split(":", 1)[-1]))


def node_at(nodes, anchor):
    """(node, []) for the node `anchor` names, else (None, candidates): at most
    ANCHOR_CANDIDATES anchors of the same name, in source order."""
    want = pct_decode(str(anchor))
    for n in nodes:
        if n["anchor"] == anchor or pct_decode(n["anchor"]) == want:
            return n, []
    name = anchor_name(anchor)
    cands = [n["anchor"] for n in nodes if name and anchor_name(n["anchor"]) == name]
    return None, cands[:ANCHOR_CANDIDATES]


def near_of(dist, paths, k, bits):
    """The `k` nearest live files: Hamming distance, a tie by path (then id);
    `score` = 1 - distance / bits, so 1 is the same vector."""
    got = sorted((d, paths[f], f) for f, d in dist.items() if f in paths)[:k]
    return [{"file": f, "path": p, "score": round(1.0 - float(d) / bits, 4)}
            for d, p, f in got]


def node_args(S):
    """The arguments of the node ops, checked before any store is asked:
    an error message, or None with S['pg'] / S['k'] set."""
    a, op = S["args"], S["op"]
    try:
        if op == "outline":
            S["pg"] = list(page_args(a, OUTLINE_LIMIT, NODES_MAX))
        elif op == "links":
            S["pg"] = list(page_args(a, LINKS_LIMIT, LINKS_MAX))
        elif op == "near":
            k = a.get("k")
            S["k"] = max(1, min(NEAR_K_MAX, NEAR_K if k in (None, "") else int(k)))
    except (TypeError, ValueError):
        return "cursor, limit and k are numbers"
    return None


# ---- extractors begin (twin of ./derive and ./read; GH #944)
# The nodes and the outgoing links of a file: what a file is made of (classes,
# functions, sections, keys, pages) under anchors that survive an edit which
# only moves lines, and what it points at (imports, uses, links). `./derive`
# runs it on every head; `./read` runs it on a version that is not the head
# (an older one, a workspace), so the two copies are word for word the same
# block -- the lock `gh944_two_extractors_give_the_same_anchors` holds them
# byte for byte, like the address twins above.
#
# Standard library only (R-BC-1): a cell has no packages, and every format
# goes through ONE register, `EXTRACTORS = {fmt: [extractor, ...]}`, the
# order being the fallback chain. An extractor is `(data, pages) -> {nodes,
# links, parser}` or a built-in exception ("not readable"); a later tree-sitter
# extractor swaps one register entry and touches nothing else. Links are only
# what the syntax says (imports, `use`, written links), never a guess from a
# name. Everything here is pure: no I/O, no params, bounded loops only.

EX_DEFAULTS = {"nodes_max": 2000, "links_max": 5000, "extract_max_bytes": 2097152, "key_depth": 3}
EX_ONELINE = 120
EX_KEY_DEPTH_CAP = 32
EX_EXT = {".py": "python", ".rs": "rust", ".md": "markdown", ".markdown": "markdown",
          ".json": "json", ".toml": "toml", ".pdf": "pdf"}
EX_PY_ITEM = re.compile(r"[ \t\f]*(?:async[ \t]+)?(def|class)[ \t]+([^\W\d]\w*)")
EX_MD_FENCE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
EX_MD_HEAD = re.compile(r"^ {0,3}(#{1,6})(?:[ \t]+(.*?))?[ \t]*$")
EX_MD_CODE = re.compile(r"(`+)(.+?)\1")
EX_MD_REFDEF = re.compile(r"^ {0,3}\[[^\]]+\]:[ \t]*(<[^>]*>|\S+)")
EX_MD_INLINE = re.compile(r"\]\([ \t]*(<[^>]*>|[^)\s]+)(?:[ \t]+(?:\"[^\"]*\"|'[^']*'|\([^)]*\)))?[ \t]*\)")
EX_MD_AUTO = re.compile(r"<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*)>")
EX_MD_BARE = re.compile(r"(?<![\w/(<])https?://[^\s<>()\[\]]+")
EX_SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")
EX_TOML_BARE = re.compile(r"[A-Za-z0-9_-]+")


def format_of(path, mime):
    """The format of a file by its name (case-insensitive), a PDF also by its
    type; None when no extractor reads it (a binary without a name, YAML...)."""
    name = str(path or "").rsplit("/", 1)[-1].lower()
    dot = name.rfind(".")
    fmt = EX_EXT.get(name[dot:]) if dot > 0 else None
    if fmt is None and str(mime or "").split(";")[0].strip().lower() == "application/pdf":
        fmt = "pdf"
    return fmt


def anchor_part(art, name):
    """`<art>:<name>`; `%`, `#`, `@` and whitespace in the name are %XX, so an
    anchor never breaks the address `fh-..@v#anchor` it rides in."""
    out = []
    for ch in str(name):
        if ch in "%#@" or ch.isspace():
            out.append("".join("%%%02X" % b for b in ch.encode("utf-8")))
        else:
            out.append(ch)
    return "%s:%s" % (art, "".join(out))


def anchor_of(segments):
    return "/".join(anchor_part(a, n) for a, n in segments)


def unique_anchor(seen, anchor):
    """The second item with the same anchor in one file is `anchor~2`, the
    third `~3`, in source order: an anchor names one item, never two."""
    n = seen.get(anchor, 0) + 1
    seen[anchor] = n
    return anchor if n == 1 else "%s~%d" % (anchor, n)


def md_slug(text):
    """GitHub's heading slug: lower case, punctuation but `-`/`_` dropped,
    every whitespace a `-`."""
    s = re.sub(r"[^\w\s-]", "", str(text).strip().lower())
    return re.sub(r"\s", "-", s)


def resolve_link(path, target):
    """A written relative link as the absolute space path it points at; `..`
    folded, `#frag` kept; a bare `#frag` is this file. None above the root:
    a link that leaves the space is no edge."""
    target = str(target)
    if target.startswith("#"):
        return str(path) + target
    t, sep, frag = target.partition("#")
    parts = [] if t.startswith("/") else [p for p in str(path).split("/") if p][:-1]
    for seg in t.split("/"):
        if seg in ("", "."):
            continue
        if seg == "..":
            if not parts:
                return None
            parts.pop()
        else:
            parts.append(seg)
    return "/" + "/".join(parts) + ("#" + frag if sep else "")


def _ex_text(data):
    return bytes(data or b"").decode("utf-8-sig")


def _ex_join(parent, part):
    return part if not parent else parent + "/" + part


def _ex_node(ctx, kind, parent, part, frm, to, unit="line", oneline=None):
    # A key's pointer already names its whole path: it is one segment, its
    # parent only a field. Every other item nests under its parent's anchor.
    anchor = unique_anchor(ctx["seen"], part if kind == "key" else _ex_join(parent, part))
    if oneline is None:
        lines = ctx["lines"]
        oneline = lines[frm - 1] if 0 < frm <= len(lines) else ""
    ctx["nodes"].append({"anchor": anchor, "kind": kind, "parent": parent or "", "unit": unit,
                         "from": frm, "to": to, "oneline": str(oneline).strip()[:EX_ONELINE]})
    return anchor


def _ex_ctx(text):
    return {"lines": text.split("\n"), "seen": {}, "nodes": [], "links": []}


def _ex_link(ctx, kind, from_anchor, target, pos, alias=None):
    link = {"kind": kind, "from_anchor": from_anchor or "", "target_name": target, "pos": pos}
    # `alias` is only what the syntax binds with `as` (python imports): a
    # link without one has no key at all, so the plain form stays the plain
    # form and an empty alias never reads as a name.
    if alias:
        link["alias"] = alias
    ctx["links"].append(link)


# ---- python: `ast` first, the indentation scanner when `ast` cannot read it

def _ex_dotted(e):
    if isinstance(e, ast.Name):
        return e.id
    if isinstance(e, ast.Attribute):
        head = _ex_dotted(e.value)
        return None if head is None else head + "." + e.attr
    return None


def _ex_py_walk(node, parent, ctx, mods):
    for ch in ast.iter_child_nodes(node):
        if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            kind = "class" if isinstance(ch, ast.ClassDef) else "def"
            anchor = _ex_node(ctx, kind, parent, anchor_part(kind, ch.name),
                              ch.lineno, getattr(ch, "end_lineno", None) or ch.lineno)
            _ex_py_walk(ch, anchor, ctx, mods)
            continue
        if isinstance(ch, ast.Import):
            for a in ch.names:
                _ex_link(ctx, "import", parent, a.name, ch.lineno, a.asname)
        elif isinstance(ch, ast.ImportFrom):
            base = "." * (ch.level or 0) + (ch.module or "")
            for a in ch.names:
                _ex_link(ctx, "import", parent, base + ":" + a.name, ch.lineno, a.asname)
        elif isinstance(ch, ast.Call):
            f = ch.func
            if isinstance(f, ast.Name):
                _ex_link(ctx, "call", parent, f.id, ch.lineno)
            elif isinstance(f, ast.Attribute):
                # Only a module bound by `import` is a callee we know; any
                # other `obj.meth()` would be a guess about `obj`.
                owner = _ex_dotted(f.value)
                if owner is not None and owner in mods:
                    _ex_link(ctx, "call", parent, mods[owner] + ":" + f.attr, ch.lineno)
        _ex_py_walk(ch, parent, ctx, mods)


def extract_python_ast(data, pages):
    text = _ex_text(data)
    tree = ast.parse(text)
    mods = {}
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.asname:
                    mods[a.asname] = a.name
                else:
                    parts = a.name.split(".")
                    for k in range(1, len(parts) + 1):
                        mods[".".join(parts[:k])] = ".".join(parts[:k])
    ctx = _ex_ctx(text)
    _ex_py_walk(tree, "", ctx, mods)
    ctx["links"].sort(key=lambda l: l["pos"])
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "ast"}


def _ex_py_blank(text):
    """The text with comments dropped and string contents blanked (quotes and
    line ends stay), and for every line whether it starts a logical line --
    not inside brackets, a string or after a backslash. A line opening with
    `def`/`class` closes any bracket left open: no expression holds those
    keywords, and one unclosed bracket must not swallow the rest of a file
    that `ast` already refused."""
    out, starts = [], []
    depth, cont, start, i, n = 0, False, True, 0, len(text)
    while i < n:
        if start:
            if depth and EX_PY_ITEM.match(text, i):
                depth = 0
            starts.append(depth == 0 and not cont)
            start, cont = False, False
        c = text[i]
        if c == "#":
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if c in "\"'":
            q = c * 3 if text.startswith(c * 3, i) else c
            j = i + len(q)
            done = False
            while j < n:
                if text[j] == "\\":
                    j += 2
                    continue
                if text.startswith(q, j):
                    done = True
                    break
                if len(q) == 1 and text[j] == "\n":
                    break
                j += 1
            out.append(q)
            for ch in text[i + len(q):min(j, n)]:
                if ch == "\n":
                    out.append("\n")
                    starts.append(False)
                else:
                    out.append(" ")
            if done:
                out.append(q)
                j += len(q)
            i = j
            continue
        if c == "\\" and text.startswith("\n", i + 1):
            cont = True
            out.append(" ")
            i += 1
            continue
        if c in "([{":
            depth += 1
        elif c in ")]}":
            depth = max(0, depth - 1)
        elif c == "\n":
            start = True
        out.append(c)
        i += 1
    lines = "".join(out).split("\n")
    starts += [False] * (len(lines) - len(starts))
    return lines, starts


def extract_python_scan(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    blank, starts = _ex_py_blank(text)
    stack, last = [], 0
    for ln, (line, first) in enumerate(zip(blank, starts), 1):
        if not line.strip():
            continue
        if first:
            ind = len(line.expandtabs(8)) - len(line.expandtabs(8).lstrip())
            while stack and stack[-1][0] >= ind:
                ctx["nodes"][stack.pop()[1]]["to"] = last
            m = EX_PY_ITEM.match(line)
            if m:
                kind = m.group(1)
                anchor = _ex_node(ctx, kind, stack[-1][2] if stack else "",
                                  anchor_part(kind, m.group(2)), ln, ln)
                stack.append((ind, len(ctx["nodes"]) - 1, anchor))
        last = ln
    while stack:
        ctx["nodes"][stack.pop()[1]]["to"] = last
    return {"nodes": ctx["nodes"], "links": [], "parser": "scan"}


# ---- rust: a token scanner (strings, raw strings, chars, nested comments)

def _ex_rs_tokens(text):
    toks, i, n, line = [], 0, len(text), 1
    while i < n:
        c = text[i]
        if c == "\n":
            line += 1
            i += 1
            continue
        if c.isspace():
            i += 1
            continue
        if text.startswith("//", i):
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if text.startswith("/*", i):
            depth, j = 1, i + 2
            while depth:
                if j >= n:
                    raise ValueError("unterminated block comment")
                if text.startswith("/*", j):
                    depth, j = depth + 1, j + 2
                elif text.startswith("*/", j):
                    depth, j = depth - 1, j + 2
                else:
                    j += 1
            line += text.count("\n", i, j)
            i = j
            continue
        if c == "_" or c.isalpha():
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()):
                j += 1
            w = text[i:j]
            if w in ("r", "br", "cr") and j < n and text[j] in "\"#":
                k = j
                while k < n and text[k] == "#":
                    k += 1
                if k < n and text[k] == "\"":
                    close = "\"" + "#" * (k - j)
                    e = text.find(close, k + 1)
                    if e < 0:
                        raise ValueError("unterminated raw string")
                    toks.append(("\"", "str", line))
                    line += text.count("\n", i, e)
                    i = e + len(close)
                    continue
                if w == "r" and k == j + 1 and k < n and (text[k] == "_" or text[k].isalpha()):
                    m = k + 1
                    while m < n and (text[m] == "_" or text[m].isalnum()):
                        m += 1
                    toks.append((text[k:m], "rid", line))
                    i = m
                    continue
            if w in ("b", "c") and j < n and text[j] == "\"" or w == "b" and j < n and text[j] == "'":
                i = j
                continue
            toks.append((w, "id", line))
            i = j
            continue
        if c.isdigit():
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()
                             or text[j] == "." and j + 1 < n and text[j + 1].isdigit()):
                j += 1
            toks.append((text[i:j], "lit", line))
            i = j
            continue
        if c == "\"":
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError("unterminated string")
                if text[j] == "\\":
                    j += 2
                    continue
                if text[j] == "\"":
                    break
                j += 1
            toks.append(("\"", "str", line))
            line += text.count("\n", i, j)
            i = j + 1
            continue
        if c == "'":
            if text.startswith("\\", i + 1):
                j = text.find("'", i + 3)
                if j < 0:
                    raise ValueError("unterminated char")
                toks.append(("'", "chr", line))
                i = j + 1
                continue
            if i + 2 < n and text[i + 2] == "'" and text[i + 1] != "\n":
                toks.append(("'", "chr", line))
                i += 3
                continue
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()):
                j += 1
            toks.append((text[i:j], "life", line))
            i = j
            continue
        two = text[i:i + 2]
        if two in ("::", "->", "=>"):
            toks.append((two, "p", line))
            i += 2
            continue
        toks.append((c, "p", line))
        i += 1
    return toks


def _ex_rs_match(toks):
    """Every opening bracket's closing partner; an unbalanced file raises --
    a scanner that guessed past it would invent items."""
    pairs = {")": "(", "]": "[", "}": "{"}
    match, stack = {}, []
    for k, t in enumerate(toks):
        if t[1] != "p":
            continue
        if t[0] in ("(", "[", "{"):
            stack.append(k)
        elif t[0] in pairs:
            if not stack or toks[stack[-1]][0] != pairs[t[0]]:
                raise ValueError("unbalanced brackets at line %d" % t[2])
            match[stack.pop()] = k
    if stack:
        raise ValueError("unclosed bracket at line %d" % toks[stack[-1]][2])
    return match


def _ex_rs_is(t, word):
    return t[1] == "id" and t[0] == word


def _ex_rs_body(toks, match, k, end):
    """From `k`, the index of the item's `{` or `;` (brackets skipped), or end."""
    while k < end:
        v = toks[k][0]
        if toks[k][1] == "p" and v in ("(", "["):
            k = match[k] + 1
            continue
        if toks[k][1] == "p" and v in ("{", ";"):
            return k
        k += 1
    return end


def _ex_rs_type(ts):
    """The bare name of a type in an `impl` head: references, lifetimes,
    generics and the path cut away (`&'a mut crate::a::Foo<T>` -> `Foo`)."""
    neg = ""
    while ts and (ts[0][1] == "life" or ts[0][0] in ("&", "*", "mut", "dyn", "const", "!")):
        if ts[0][0] == "!":
            neg = "!"
        ts = ts[1:]
    depth, path = 0, []
    for t in ts:
        if t[0] == "<":
            depth += 1
        elif t[0] == ">":
            depth -= 1
        elif depth == 0:
            path.append(t)
    names = [t[0] for t in path if t[1] in ("id", "rid")]
    if path and all(t[1] in ("id", "rid") or t[0] == "::" for t in path) and names:
        return neg + names[-1]
    return neg + "".join(t[0] for t in ts)


def _ex_rs_impl(head):
    """`impl<G> [Trait for] Type [where ...]` -> (type, trait or "")."""
    if head and head[0][0] == "<":
        depth, k = 0, 0
        while k < len(head):
            if head[k][0] == "<":
                depth += 1
            elif head[k][0] == ">":
                depth -= 1
                if depth == 0:
                    break
            k += 1
        head = head[k + 1:]
    depth, cut, split = 0, len(head), -1
    for k, t in enumerate(head):
        if t[0] == "<":
            depth += 1
        elif t[0] == ">":
            depth -= 1
        elif depth == 0 and _ex_rs_is(t, "where"):
            cut = k
            break
        elif depth == 0 and _ex_rs_is(t, "for"):
            split = k
    head = head[:cut]
    if split < 0:
        return _ex_rs_type(head), ""
    return _ex_rs_type(head[split + 1:]), _ex_rs_type(head[:split])


def _ex_rs_use(ts, prefix):
    """The paths of one `use` tree: `a::{b, c}` two, `a::*` kept, `as` dropped,
    `a::{self, b}` -> `a`, `a::b`."""
    out, path, k = [], list(prefix), 0
    while k < len(ts):
        v = ts[k][0]
        if v == "::":
            if not path:
                path.append("")
            k += 1
            continue
        if v == "{":
            depth, j, part, parts = 0, k + 1, [], []
            while j < len(ts):
                w = ts[j][0]
                if w == "{":
                    depth += 1
                elif w == "}":
                    if depth == 0:
                        break
                    depth -= 1
                if w == "," and depth == 0:
                    parts.append(part)
                    part = []
                else:
                    part.append(ts[j])
                j += 1
            parts.append(part)
            for p in parts:
                if p:
                    out += _ex_rs_use(p, path)
            return out
        if _ex_rs_is(ts[k], "as"):
            break
        path.append(v)
        k += 1
    if len(path) > 1 and path[-1] == "self" and len(path) > len(prefix) and prefix:
        path = path[:-1]
    if path:
        out.append("::".join(path))
    return out


def _ex_rs_scope(ctx, i, end, parent):
    toks, match = ctx["toks"], ctx["match"]
    inherent = {}
    start = None
    while i < end:
        t = toks[i]
        v, kind = t[0], t[1]
        if kind == "p" and v == "#":
            j = i + 1
            if j < end and toks[j][0] == "!":
                j += 1
            if j < end and toks[j][0] == "[":
                i = match[j] + 1
                start = None
                continue
            i += 1
            continue
        if start is None:
            start = i
        frm = toks[start][2]
        if kind == "p":
            if v == ";":
                start = None
            elif v in ("(", "[", "{"):
                if v == "{":
                    start = None
                i = match[i] + 1
                continue
            i += 1
            continue
        nxt = toks[i + 1] if i + 1 < end else ("", "", 0)
        if kind == "id" and v == "use":
            k = i + 1
            while k < end and toks[k][0] != ";":
                k = match[k] if toks[k][0] in ("{", "(", "[") and toks[k][1] == "p" else k
                k += 1
            for target in _ex_rs_use(toks[i + 1:k], []):
                _ex_link(ctx, "import", parent, target, t[2])
            i, start = k + 1, None
            continue
        if kind == "id" and v == "macro_rules" and nxt[0] == "!" and i + 2 < end \
                and toks[i + 2][1] in ("id", "rid"):
            k = i + 3
            if k < end and toks[k][0] in ("{", "(", "["):
                close = match[k]
                if toks[k][0] != "{" and close + 1 < end and toks[close + 1][0] == ";":
                    close += 1
                _ex_node(ctx, "macro", parent, anchor_part("macro", toks[i + 2][0]),
                         frm, toks[close][2])
                i, start = close + 1, None
                continue
        if kind == "id" and v in ("fn", "struct", "enum", "trait", "mod") and nxt[1] in ("id", "rid"):
            k = _ex_rs_body(toks, match, i + 2, end)
            if v == "mod" and (k >= end or toks[k][0] != "{"):
                i, start = k + 1, None
                continue
            close = match[k] if k < end and toks[k][0] == "{" else min(k, end - 1)
            anchor = _ex_node(ctx, v, parent, anchor_part(v, nxt[0]), frm, toks[close][2])
            if v in ("trait", "mod") and k < end and toks[k][0] == "{":
                _ex_rs_scope(ctx, k + 1, close, anchor)
            i, start = close + 1, None
            continue
        if kind == "id" and v == "impl":
            k = _ex_rs_body(toks, match, i + 1, end)
            if k >= end or toks[k][0] != "{":
                i, start = k + 1, None
                continue
            close = match[k]
            ty, trait = _ex_rs_impl(toks[i + 1:k])
            name = ty + ("+" + trait if trait else "")
            if not trait and ty in inherent:
                # Methods hang on the type, not on the block: a second
                # inherent block of the same type is no item of its own.
                anchor = inherent[ty]
            else:
                anchor = _ex_node(ctx, "impl", parent, anchor_part("impl", name), frm, toks[close][2])
                if not trait:
                    inherent[ty] = anchor
            _ex_rs_scope(ctx, k + 1, close, anchor)
            i, start = close + 1, None
            continue
        i += 1


def extract_rust_scan(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    ctx["toks"] = _ex_rs_tokens(text)
    ctx["match"] = _ex_rs_match(ctx["toks"])
    _ex_rs_scope(ctx, 0, len(ctx["toks"]), "")
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "scan"}


# ---- markdown: flat sections under GitHub slugs, written links

def _ex_md_links(ctx, line, sec, ln):
    # Spans already taken are blanked, never cut out: the columns stay, and
    # the links of a line come out in the order they are written.
    s = EX_MD_CODE.sub(lambda m: " " * len(m.group(0)), line)
    found = []
    ref = EX_MD_REFDEF.match(s)
    if ref:
        found.append((ref.start(1), ref.group(1)))
        s = ""
    for m in EX_MD_INLINE.finditer(s):
        found.append((m.start(1), m.group(1)))
    s = EX_MD_INLINE.sub(lambda m: " " * len(m.group(0)), s)
    for m in EX_MD_AUTO.finditer(s):
        found.append((m.start(1), m.group(1)))
    s = EX_MD_AUTO.sub(lambda m: " " * len(m.group(0)), s)
    for m in EX_MD_BARE.finditer(s):
        found.append((m.start(), m.group(0).rstrip(".,;:!?'\"")))
    found.sort(key=lambda f: f[0])
    for _, target in found:
        target = target.strip()
        if target.startswith("<") and target.endswith(">"):
            target = target[1:-1].strip()
        if not target:
            continue
        kind = "url" if EX_SCHEME.match(target) or target.startswith("//") else "link"
        _ex_link(ctx, kind, sec, target, ln)


def extract_markdown(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    fence, sec, slugs, heads = None, "", {}, []
    for ln, raw in enumerate(ctx["lines"], 1):
        line = raw.rstrip("\r")
        f = EX_MD_FENCE.match(line)
        if fence is not None:
            if f and f.group(1)[0] == fence[0] and len(f.group(1)) >= fence[1] and not f.group(2).strip():
                fence = None
            continue
        if f and not (f.group(1)[0] == "`" and "`" in f.group(2)):
            fence = (f.group(1)[0], len(f.group(1)))
            continue
        h = EX_MD_HEAD.match(line)
        if h:
            title = re.sub(r"(^|[ \t]+)#+$", "", h.group(2) or "").strip()
            base = md_slug(title)
            slug = base
            while slug in slugs:
                slugs[base] += 1
                slug = "%s-%d" % (base, slugs[base])
            slugs[slug] = 0
            sec = _ex_node(ctx, "sec", "", anchor_part("sec", slug), ln, ln)
            heads.append((len(ctx["nodes"]) - 1, len(h.group(1))))
        _ex_md_links(ctx, line, sec, ln)
    total = len(ctx["lines"])
    if total > 1 and ctx["lines"][-1] == "":
        total -= 1
    for k, (idx, level) in enumerate(heads):
        to = total
        for idx2, level2 in heads[k + 1:]:
            if level2 <= level:
                to = ctx["nodes"][idx2]["from"] - 1
                break
        ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], to)
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "markdown"}


# ---- json / toml: keys as RFC 6901 pointers, arrays only as their key

def _ex_pointer(parts):
    return "".join("/" + str(p).replace("~", "~0").replace("/", "~1") for p in parts)


def _ex_json_tokens(text):
    toks, i, n, line = [], 0, len(text), 1
    while i < n:
        c = text[i]
        if c == "\n":
            line += 1
            i += 1
        elif c in " \t\r":
            i += 1
        elif c == "\"":
            j = i + 1
            while j < n and text[j] != "\"":
                j += 2 if text[j] == "\\" else 1
            toks.append(("s", json.loads(text[i:j + 1]), line))
            i = j + 1
        elif c in "{}[]:,":
            toks.append((c, None, line))
            i += 1
        else:
            j = i
            while j < n and text[j] not in " \t\r\n{}[]:,\"":
                j += 1
            toks.append(("v", text[i:j], line))
            i = j
    return toks


def _ex_json_value(ctx, toks, i, parts, parent, depth):
    """Walk one value from token `i`; returns (next index, its last line)."""
    t = toks[i]
    if t[0] == "[":
        level = 0
        while True:
            if toks[i][0] in ("[", "{"):
                level += 1
            elif toks[i][0] in ("]", "}"):
                level -= 1
                if level == 0:
                    return i + 1, toks[i][2]
            i += 1
    if t[0] != "{":
        return i + 1, t[2]
    i += 1
    if toks[i][0] == "}":
        return i + 1, toks[i][2]
    while True:
        key = toks[i]
        sub = parts + [key[1]]
        idx, anchor = None, parent
        if len(sub) <= depth:
            anchor = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(sub)), key[2], key[2])
            idx = len(ctx["nodes"]) - 1
        i, last = _ex_json_value(ctx, toks, i + 2, sub, anchor, depth)
        if idx is not None:
            ctx["nodes"][idx]["to"] = last
        if toks[i][0] == ",":
            i += 1
            continue
        return i + 1, toks[i][2]


def extract_json_at(data, depth):
    text = _ex_text(data)
    json.loads(text)
    ctx = _ex_ctx(text)
    _ex_json_value(ctx, _ex_json_tokens(text), 0, [], "", depth)
    return {"nodes": ctx["nodes"], "links": [], "parser": "json"}


def extract_json(data, pages):
    return extract_json_at(data, EX_KEY_DEPTH_CAP)


def _ex_toml_key(s, pos):
    parts = []
    while True:
        while pos < len(s) and s[pos] in " \t":
            pos += 1
        if pos < len(s) and s[pos] == "\"":
            j = pos + 1
            while j < len(s) and s[j] != "\"":
                j += 2 if s[j] == "\\" else 1
            parts.append(json.loads(s[pos:j + 1]))
            pos = j + 1
        elif pos < len(s) and s[pos] == "'":
            j = s.find("'", pos + 1)
            parts.append(s[pos + 1:j])
            pos = j + 1
        else:
            m = EX_TOML_BARE.match(s, pos)
            if not m:
                raise ValueError("no key")
            parts.append(m.group(0))
            pos = m.end()
        while pos < len(s) and s[pos] in " \t":
            pos += 1
        if pos < len(s) and s[pos] == ".":
            pos += 1
            continue
        return parts, pos


def _ex_toml_end(lines, i, col):
    """The last line of a value starting at (`i`, `col`): brackets and
    multi-line strings may carry it over several lines."""
    depth, quote = 0, None
    while i < len(lines):
        s, k = lines[i], col
        while k < len(s):
            if quote:
                if quote[0] == "\"" and s[k] == "\\":
                    k += 2
                    continue
                if s.startswith(quote, k):
                    k += len(quote)
                    quote = None
                    continue
                k += 1
                continue
            c = s[k]
            if c == "#":
                break
            if c in "\"'":
                quote = c * 3 if s.startswith(c * 3, k) else c
                k += len(quote)
                continue
            if c in "[{":
                depth += 1
            elif c in "]}":
                depth -= 1
            k += 1
        if quote is not None and len(quote) == 1:
            quote = None
        if depth <= 0 and quote is None:
            return i
        i, col = i + 1, 0
    return len(lines) - 1


def _ex_toml_lookup(doc, parts):
    """The value at `parts`; None past an array (its tables are no nodes)."""
    cur = doc
    for p in parts:
        cur = cur.get(p) if isinstance(cur, dict) else None
    return cur


def _ex_toml_ensure(ctx, doc, known, parts, frm, to, depth):
    """A node for every prefix of `parts` not seen yet; none inside an array."""
    parent = ""
    for k in range(1, len(parts) + 1):
        sub = tuple(parts[:k])
        if sub in known:
            parent = known[sub]
            if parent is None:
                return None
            continue
        if k > depth:
            return None
        up = _ex_toml_lookup(doc, parts[:k - 1])
        if isinstance(up, list):
            known[sub] = None
            return None
        parent = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(sub)), frm, to)
        known[sub] = parent
    return parent


def _ex_toml_inline(ctx, value, parts, parent, frm, to, depth):
    if not isinstance(value, dict) or len(parts) >= depth:
        return
    for key, sub in value.items():
        anchor = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(parts + [key])), frm, to)
        _ex_toml_inline(ctx, sub, parts + [key], anchor, frm, to, depth)


def extract_toml_at(data, depth):
    import tomllib
    text = _ex_text(data)
    doc = tomllib.loads(text)
    ctx = _ex_ctx(text)
    lines = [l.rstrip("\r") for l in ctx["lines"]]
    known, table, open_tables, last, i = {}, [], [], 0, 0
    while i < len(lines):
        s = lines[i].strip()
        if not s or s.startswith("#"):
            i += 1
            continue
        if s.startswith("["):
            for idx in open_tables:
                ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], last)
            arr = s.startswith("[[")
            table, _ = _ex_toml_key(s, 2 if arr else 1)
            before = len(ctx["nodes"])
            _ex_toml_ensure(ctx, doc, known, table, i + 1, i + 1, depth)
            open_tables = list(range(before, len(ctx["nodes"])))
            last = i + 1
            i += 1
            continue
        col = len(lines[i]) - len(lines[i].lstrip())
        parts, pos = _ex_toml_key(lines[i], col)
        end = _ex_toml_end(lines, i, pos + 1)
        full = table + parts
        parent = _ex_toml_ensure(ctx, doc, known, full, i + 1, end + 1, depth)
        if parent is not None:
            value = _ex_toml_lookup(doc, full)
            _ex_toml_inline(ctx, value, full, parent, i + 1, end + 1, depth)
        last = end + 1
        i = end + 1
    for idx in open_tables:
        ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], last)
    return {"nodes": ctx["nodes"], "links": [], "parser": "toml"}


def extract_toml(data, pages):
    return extract_toml_at(data, EX_KEY_DEPTH_CAP)


# ---- pdf: one node per page of the derived text

def extract_pdf(data, pages):
    if pages is None:
        raise ValueError("no page text")
    ctx = _ex_ctx("")
    rows = sorted(pages, key=lambda p: int(p.get("part") or 0))
    for p in rows:
        n = int(p.get("part") or 0)
        body = str(p.get("text", p.get("body")) or "")
        first = next((l for l in body.split("\n") if l.strip()), "")
        _ex_node(ctx, "page", "", anchor_part("page", n), n, n, "page", first)
    return {"nodes": ctx["nodes"], "links": [], "parser": "pdf"}


# ---- the file vector of `near`: a bitwise majority over the section bits

def file_vector(blobs):
    """The bitwise majority (a tie is 1) over the sign bits `./embed` packs
    per section, base64 like them; "" when there is none or they differ in
    length."""
    raws = []
    for b in blobs or []:
        try:
            raws.append(base64.b64decode(str(b), validate=True))
        except (ValueError, TypeError):
            return ""
    if not raws or len({len(r) for r in raws}) != 1 or not raws[0]:
        return ""
    out = bytearray(len(raws[0]))
    for i in range(len(out)):
        for bit in range(8):
            mask = 1 << (7 - bit)
            if 2 * sum(1 for r in raws if r[i] & mask) >= len(raws):
                out[i] |= mask
    return base64.b64encode(bytes(out)).decode("ascii")


def hamming_b64(a, b):
    try:
        x = base64.b64decode(str(a), validate=True)
        y = base64.b64decode(str(b), validate=True)
    except (ValueError, TypeError):
        return None
    if len(x) != len(y) or not x:
        return None
    return sum(bin(p ^ q).count("1") for p, q in zip(x, y))


EXTRACTORS = {
    "python": [extract_python_ast, extract_python_scan],
    "rust": [extract_rust_scan],
    "markdown": [extract_markdown],
    "json": [extract_json],
    "toml": [extract_toml],
    "pdf": [extract_pdf],
}


def _ex_int(limits, key):
    v = (limits or {}).get(key)
    try:
        return max(0, int(float(v)))
    except (TypeError, ValueError):
        return EX_DEFAULTS[key]


def extract(path, mime, data, pages, limits):
    """The one entry point: format, size cap, the fallback chain, the key
    depth, resolved links, the caps. Never raises; what went wrong is the
    `mark` (`no_extractor`, `too_large`, `unparsable`, `truncated`)."""
    out = {"fmt": "", "parser": "", "mark": "", "nodes": [], "links": []}
    fmt = format_of(path, mime)
    if fmt is None:
        out["mark"] = "no_extractor"
        return out
    out["fmt"] = fmt
    data = bytes(data or b"")
    if fmt == "pdf":
        size = sum(len(str(p.get("text", p.get("body")) or "").encode("utf-8")) for p in pages or [])
    else:
        size = len(data)
    if size > _ex_int(limits, "extract_max_bytes"):
        out["mark"] = "too_large"
        return out
    if fmt != "pdf" and not data:
        return out
    got = None
    for fn in EXTRACTORS.get(fmt, []):
        try:
            got = fn(data, pages)
        except Exception:
            continue
        break
    if got is None:
        out["mark"] = "unparsable"
        return out
    nodes, depth = [], {}
    keep = _ex_int(limits, "key_depth")
    for n in got["nodes"]:
        if n["kind"] == "key":
            depth[n["anchor"]] = depth.get(n["parent"], 0) + 1
            if depth[n["anchor"]] > keep:
                continue
        nodes.append(dict(n, parser=got["parser"]))
    links, once = [], set()
    for l in got["links"]:
        target = l["target_name"]
        if l["kind"] == "link":
            target = resolve_link(path, target)
            if target is None:
                continue
        # The alias is part of what an import is: `import m as a` and
        # `import m as b` bind two names, two links.
        key = (l["from_anchor"], l["kind"], target, l.get("alias", ""))
        if key in once:
            continue
        once.add(key)
        links.append(dict(l, target_name=target))
    out["parser"] = got["parser"]
    if len(nodes) > _ex_int(limits, "nodes_max") or len(links) > _ex_int(limits, "links_max"):
        out["mark"] = "truncated"
    out["nodes"] = nodes[:_ex_int(limits, "nodes_max")]
    out["links"] = links[:_ex_int(limits, "links_max")]
    return out
# ---- extractors end

# Written out rather than imported from the standard URL library: a shipped
# cell that imports it reads as a network speaker to the sandbox sweep
# (GH #144), and read never speaks the network. Word for word the copy in
# `./write`; a lone surrogate in an address once raised here (GH #947,
# ledger 15) and the request died without its answer.
def pct_decode(s):
    """`%XX` escapes of an anchor back to their bytes (UTF-8), as `./read`
    matches an anchor. Never raises: a lone surrogate passes the encoding and
    an invalid byte sequence decodes as a replacement character."""
    return re.sub(rb"%([0-9A-Fa-f]{2})", lambda m: bytes([int(m.group(1), 16)]),
                  str(s).encode("utf-8", "surrogatepass")).decode("utf-8", "replace")




# ============================================================ PHASES

def files_cols():
    return ["file", "path", "kind", "mime", "head", "head_seq", "lock", "tomb",
            "oneline", "bytes", "lines", "born_at"]


def prefix_lookup(cid, file_id, pfx):
    return (cid, sel("versions", ["version"],
                     {"file": file_id, "version": {"gte": pfx}} if len(pfx) < 64
                     else {"file": file_id, "version": pfx},
                     [("version", "asc")], CANDIDATES_MAX))


def pick(lg, cid, pfx):
    """A hex prefix within one file -> (full, error, candidates)."""
    got = [str(r.get("version") or "") for r in rows(lg, cid)]
    got = [v for v in got if v.startswith(pfx)]
    if not got:
        return "", "version_unknown", []
    if len(got) > 1:
        return "", "version_ambiguous", [v12(v) for v in got]
    return got[0], "", []


def start(S):
    op = S["op"]
    if op in SPACE_OPS:
        args = S["args"]
        if op == "list":
            prefix = str(args.get("prefix") or "/")
            if not prefix.startswith("/"):
                fail(S, "bad_request", "a prefix starts with /", parked=False)
            depth = int(args.get("depth") or 1)
            if depth < 1:
                fail(S, "bad_request", "depth is at least 1", parked=False)
            # No `like` and one operator per column: the range starts at the
            # prefix, and the rows past it are cut off here.
            where = {"path": {"gte": prefix}, "tomb": "", "head": {"neq": ""}}
            S["list"] = {"prefix": prefix, "depth": depth}
            # GH #947: the directory rows down to one level below the cut --
            # the entries' own rows and their children, counted as `subdirs`.
            base = prefix if prefix.endswith("/") else prefix + "/"
            dwhere = {"path": {"gte": base}, "depth": {"lte": dir_depth(base) + depth + 1},
                      "tomb": ""}
            next_phase(S, "list", [
                ("l-files", sel("files", ["file", "path", "bytes", "lines"], where,
                                [("path", "asc")], LIST_SCAN + 1)),
                ("l-dirs", sel("dirs", DIR_COLS, dwhere, [("path", "asc")], LIST_SCAN + 1))],
                first=True)
        if op == "dir_info":
            got = dir_args(args)
            if isinstance(got, str):
                fail(S, "bad_request", got, parked=False)
            path, cur, limit = got
            S["dir"] = {"path": path, "cursor": cur, "limit": limit}
            kids = {"parent": path, "tomb": ""}
            # GH #973 M-2: the files by their path, not by `files.dir` -- a
            # row written before `dir` existed has none (no backfill). The
            # range from the cursor (or `path/`) on holds deeper files too;
            # `on_dir` keeps the direct ones. Fix round 1 (review M-4): never
            # below `path/` -- a cursor before it (`/` for `/a`) read a whole
            # window of foreign rows and answered an empty page with no `next`.
            files = {"path": {"gt": max(cur, dir_base(path))}, "tomb": "",
                     "head": {"neq": ""}}
            if cur:
                kids["path"] = {"gt": cur}
            next_phase(S, "dir", [
                ("d-row", sel("dirs", DIR_COLS, {"path": path}, None, 1)),
                ("d-n", sel("dirs", ["path"], {"parent": path, "tomb": ""}, None, SUBDIRS_MAX)),
                ("d-kids", sel("dirs", ["path", "files", "bytes", "nodes", "dirty", "summary"],
                               kids, [("path", "asc")], limit + 1)),
                ("d-files", sel("files", ["file", "path", "kind", "mime", "head", "head_seq",
                                          "bytes", "lines", "oneline"],
                                files, [("path", "asc")], LIST_SCAN + 1))], first=True)
        glob = str(args.get("glob") or "")
        if not glob or len(glob) > PATTERN_MAX:
            fail(S, "bad_request", "find takes a glob", parked=False)
        limit = min(FIND_LIMIT_MAX, max(1, int(args.get("limit") or FIND_LIMIT)))
        S["find"] = {"glob": glob, "limit": limit, "after": "", "scanned": 0, "hits": []}
        next_phase(S, "find", [find_page(S)], first=True)
    addr = S["addr"]
    ops = []
    if addr["file"]:
        ops.append(("f-row", sel("files", files_cols(), {"file": addr["file"]}, None, 1)))
    else:
        ops.append(("f-row", sel("files", files_cols(), {"path": addr["path"], "tomb": ""},
                                 [("born_at", "asc")], 2)))
    if S.get("ws_name"):
        ops.append(("w-row", sel("ws", ["ws", "name", "root", "base_seq", "state"],
                                 {"name": S["ws_name"], "state": "open"},
                                 [("opened_at", "desc")], 1)))
    next_phase(S, "file", ops, first=True)


def find_page(S):
    f = S["find"]
    where = {"tomb": "", "head": {"neq": ""}}
    if f["after"]:
        where["path"] = {"gt": f["after"]}
    return ("f-page", sel("files", ["file", "path"], where, [("path", "asc")], FIND_PAGE))


def on_find(S, lg):
    f = S["find"]
    page = rows(lg, "f-page")
    for r in page:
        path = str(r.get("path") or "")
        if fnmatch.fnmatchcase(path, f["glob"]) and len(f["hits"]) < f["limit"] + 1:
            f["hits"].append({"file": str(r.get("file")), "path": path})
    f["scanned"] += len(page)
    if page:
        f["after"] = str(page[-1].get("path") or "")
    done = len(page) < FIND_PAGE or len(f["hits"]) > f["limit"] or f["scanned"] >= FIND_SCAN
    if not done:
        next_phase(S, "find", [find_page(S)])
    more = len(f["hits"]) > f["limit"] or (len(page) == FIND_PAGE and f["scanned"] >= FIND_SCAN)
    body = {"glob": f["glob"], "files": f["hits"][:f["limit"]]}
    if more:
        body["more"] = True
    ok(S, body)


def on_list(S, lg):
    L = S["list"]
    got = rows(lg, "l-files")
    cut = len(got) > LIST_SCAN and str(got[LIST_SCAN].get("path") or "").startswith(L["prefix"])
    got = [r for r in got[:LIST_SCAN] if str(r.get("path") or "").startswith(L["prefix"])]
    base = L["prefix"] if L["prefix"].endswith("/") else L["prefix"] + "/"
    drows = rows(lg, "l-dirs")
    if len(drows) > LIST_SCAN and str(drows[LIST_SCAN].get("path") or "").startswith(base):
        cut = True
    entries = dir_entries(list_entries(got, L["prefix"], L["depth"]), drows[:LIST_SCAN],
                          L["prefix"], L["depth"])
    body = {"prefix": L["prefix"], "depth": L["depth"], "entries": entries}
    if cut:
        body["more"] = True
    ok(S, body)


def on_dir(S, lg):
    """`dir_info` (GH #947): the directory's row -- the root reads as zeros
    without one -- its `subdirs` counted from the living child rows, and one
    page of its children."""
    D = S["dir"]
    path = D["path"]
    row = one(lg, "d-row")
    if path != "/" and (row is None or str(row.get("tomb") or "")):
        fail(S, "not_found", "no such directory")
    if row is not None and str(row.get("tomb") or ""):
        row = None
    c = dir_counts(row)
    scan = rows(lg, "d-files")
    kids = rows(lg, "d-kids")
    files = child_files(scan, path)
    edge = ""
    if len(scan) > LIST_SCAN and str(scan[-1].get("path") or "").startswith(dir_base(path)):
        # The window ended inside the folder (its deeper files filled it):
        # this page reaches up to the last path read and the next one goes on
        # from there, so no child is skipped.
        edge = str(scan[-1].get("path") or "")
        kids = [k for k in kids if str(k.get("path") or "") <= edge]
    children, nxt = dir_children(kids, files, D["limit"])
    if edge and not nxt:
        nxt = edge
    body = {"path": path, "parent": dir_parent(path), "files": c["files"], "bytes": c["bytes"],
            "nodes": c["nodes"], "subdirs": len(rows(lg, "d-n")), "dirty": c["dirty"],
            "tags": c["tags"], "summary": c["summary"],
            "born": str((row or {}).get("born") or ""), "children": children, "next": nxt}
    ok(S, body)


def extras(S):
    """The version prefixes an op names besides its address."""
    a = S["args"]
    out = {}
    if S["op"] in ("show", "raw") + NODE_OPS and a.get("version"):
        out["x-version"] = str(a.get("version"))
    if S["op"] == "diff":
        if a.get("a"):
            out["x-a"] = str(a.get("a"))
        if a.get("b"):
            out["x-b"] = str(a.get("b"))
    return out


def on_file(S, lg):
    addr = S["addr"]
    got = rows(lg, "f-row")
    if not got:
        fail(S, "not_found", "no such file")
    if len(got) > 1:
        # Two live files under one path break the space's own rule; the older
        # birth is the one the path names.
        sys.stderr.write("file-space/read: two live files under one path\n")
    F = got[0]
    S["file_id"] = str(F.get("file") or "")
    S["frow"] = {k: F.get(k) for k in files_cols()}
    at = addr["at"]
    ws_name = S.get("ws_name") or ""
    if at == "head" and ws_name:
        at = "ws"
    if ws_name:
        W = one(lg, "w-row")
        if W is None:
            fail(S, "ws_unknown", "no open workspace of that name")
        S["wrow"] = W
    if at == "head" and str(F.get("tomb") or "") and S["op"] != "info":
        fail(S, "tombstoned", "the file was removed; its versions stay readable by version")
    # Born in a workspace (`head` ''): no file outside it, by head, version or
    # snapshot (review S M-4) -- unless a commit holds its lock: then the
    # commit decides, all or nothing (review S I-1, section 2.7).
    if (at != "ws" and not ws_name and not str(F.get("head") or "")
            and not str(F.get("lock") or "")):
        fail(S, "not_found", "no such file")
    for k, pfx in extras(S).items():
        if not HEX_RE.match(pfx):
            fail(S, "bad_request", "a version is 4 to 64 hex digits")
    if S["op"] == "diff" and not S["args"].get("a"):
        fail(S, "bad_request", "diff takes a (and b, else the addressed state)")
    fid = S["file_id"]
    if S["op"] == "near":
        # The scan is the one read of `node_runs` across files (R-FH-1's
        # exemption for `near`), bounded by `near_scan_max` and in id order,
        # so a cut is the same every time.
        next_phase(S, "near", [
            ("n-mine", sel("node_runs", ["version", "fvec"], {"file": fid}, None, 1)),
            ("n-scan", sel("node_runs", ["file", "fvec"], {"fvec": {"neq": ""}},
                           [("file", "asc")], NEAR_SCAN_MAX))])
    ops = []
    if at == "v":
        ops.append(prefix_lookup("v-main", fid, addr["ref"]))
    elif at == "snap":
        ops.append(("s-row", sel("snaps", ["name", "version"], {"file": fid, "name": addr["ref"]},
                                 [("at", "desc")], 1)))
    elif at == "ws":
        W = S["wrow"]
        ops.append(("w-file", sel("ws_files", ["base", "working", "state"],
                                  {"file": fid, "ws": str(W.get("ws") or "")}, [("at", "desc")], 1)))
        ops.append(("w-line", sel("line", ["seq", "version"],
                                  {"file": fid, "seq": {"lte": int(W.get("base_seq") or 0)}},
                                  [("seq", "desc")], 1)))
    elif str(F.get("lock") or ""):
        ops.append(("c-row", sel("commits", ["commit", "state", "plan"],
                                 {"commit": str(F.get("lock"))}, None, 1)))
    for k, pfx in extras(S).items():
        ops.append(prefix_lookup(k, fid, pfx))
    S["at"] = at
    if not ops:
        S["V"] = str(F.get("head") or "")
        to_meta(S, first=False)
    next_phase(S, "version", ops)


def on_version(S, lg):
    at = S["at"]
    F = S["frow"]
    if at == "v":
        V, err, cands = pick(lg, "v-main", S["addr"]["ref"])
        if err:
            fail(S, err, "no single version of this file starts with that prefix",
                 extra={"candidates": cands} if cands else None)
    elif at == "snap":
        r = one(lg, "s-row")
        if r is None:
            fail(S, "snap_unknown", "no snapshot of that name")
        V = str(r.get("version") or "")
    elif at == "ws":
        wf = one(lg, "w-file")
        if wf is not None:
            if str(wf.get("state") or "") == "removed":
                fail(S, "not_found", "the file is removed in this workspace")
            V = str(wf.get("working") or "")
        else:
            ln = one(lg, "w-line")
            if ln is None:
                fail(S, "not_found", "the file did not exist when the workspace opened")
            V = str(ln.get("version") or "")
    else:
        V = str(F.get("head") or "")
        c = one(lg, "c-row")
        if c is not None and str(c.get("state") or "") == "committed":
            # Past the commit point the plan's target is the file, also when
            # it is '' (a committed remove) or the head is '' (born in the
            # workspace) -- the other files of the commit already show it.
            for step in loads(c.get("plan"), []) or []:
                if isinstance(step, dict) and step.get("file") == S["file_id"]:
                    V = str(step.get("to") or "")
        if not V:
            fail(S, "not_found", "no such file")
    S["V"] = V
    xs = {}
    for k, pfx in extras(S).items():
        full, err, cands = pick(lg, k, pfx)
        if err:
            fail(S, err, "no single version of this file starts with %s" % pfx,
                 extra={"candidates": cands} if cands else None)
        xs[k] = full
    S["x"] = xs
    if S["op"] in NODE_OPS and xs.get("x-version"):
        # `outline`/`links` take their version as an argument (the tools'
        # `version`); it is the version they answer for.
        S["V"] = xs["x-version"]
    to_meta(S)


def wanted(S):
    """The full versions whose rows the op reads."""
    x = S.get("x") or {}
    op = S["op"]
    if op in ("show", "raw"):
        return [x.get("x-version") or S["V"]]
    if op == "diff":
        return [x.get("x-a") or S["V"], x.get("x-b") or S["V"]]
    return [S["V"]]


def to_meta(S, first=False):
    fid, V, op, a = S["file_id"], S["V"], S["op"], S["args"]
    vs = sorted(set(wanted(S)))
    ops = [("m-ver", sel("versions", ["version", "blocks", "bytes", "lines", "parent", "force",
                                      "made_by", "at"],
                         {"file": fid, "version": {"in": vs}}, None, len(vs)))]
    if op == "info":
        ops.append(("m-parts", sel("derived", ["part"], {"file": fid, "version": V, "kind": "text"},
                                   None, PARTS_MAX)))
        ops.append(("m-wsf", sel("ws_files", ["ws", "state"], {"file": fid}, [("at", "desc")], 200)))
        ops.append(("m-ws", sel("ws", ["ws", "name"], {"state": "open"}, [("name", "asc")], 500)))
        ops.append(("m-snaps", sel("snaps", ["name", "version"], {"file": fid},
                                   [("name", "asc")], 200)))
        # GH #947: the topics `./derive` wrote with the summary of V.
        ops.append(("m-tags", sel("summaries", ["text"],
                                  {"file": fid, "version": V, "level": "tags"},
                                  [("at", "desc")], 1)))
    elif op == "summary":
        level = str(a.get("level") or "oneline")
        if level not in ("oneline", "short"):
            fail(S, "bad_request", "level is oneline or short")
        ops.append(("m-sum", sel("summaries", ["text", "model", "at"],
                                 {"file": fid, "version": V, "level": level},
                                 [("at", "desc")], 1)))
    elif op == "history":
        limit = min(HISTORY_MAX, max(1, int(a.get("limit") or 20)))
        ops.append(("m-line", sel("line", ["seq", "version", "prev", "op", "note", "ws", "commit", "at"],
                                  {"file": fid}, [("seq", "desc")], 2 * limit)))
        S["hist_limit"] = limit
    elif op in NODE_OPS or S["addr"].get("anchor"):
        # The rows `./derive` wrote for the head; a version without a run row
        # (older, a workspace's, or a head not derived yet) is computed from
        # its blocks after the next phase -- the extractors are pure, so both
        # answer alike.
        ops.append(("n-run", sel("node_runs", ["fmt", "parser", "mark", "nodes", "links"],
                                 {"file": fid, "version": V}, None, 1)))
        if op == "links":
            off, lim = S["pg"]
            ops.append(("n-rows", sel("links", LINK_COLS, {"file": fid, "version": V},
                                      LINK_ORDER, min(off + lim, LINKS_MAX) + 1)))
        else:
            off, lim = S.get("pg") or [0, NODES_MAX]
            ops.append(("n-rows", sel("nodes", NODE_COLS, {"file": fid, "version": V},
                                      NODE_ORDER, min(off + lim, NODES_MAX) + 1)))
    next_phase(S, "meta", ops, first=first)


def on_meta(S, lg):
    op, V = S["op"], S["V"]
    vrows = {str(r.get("version")): r for r in rows(lg, "m-ver")}
    for v in wanted(S):
        if v not in vrows:
            fail(S, "corrupt", "a version the file names is missing")
    VR = vrows[V] if V in vrows else vrows[wanted(S)[0]]
    F = S["frow"]
    if op == "info":
        opened = {str(r.get("ws")): str(r.get("name")) for r in rows(lg, "m-ws")}
        wss = sorted({opened[str(r.get("ws"))] for r in rows(lg, "m-wsf")
                      if str(r.get("ws")) in opened})
        body = {"version": v12(V), "path": str(F.get("path") or ""),
                "kind": str(F.get("kind") or ""), "mime": str(F.get("mime") or ""),
                "bytes": int(VR.get("bytes") or 0), "lines": int(VR.get("lines") or 0),
                "pages": len({int(r.get("part") or 0) for r in rows(lg, "m-parts")}),
                "oneline": str(F.get("oneline") or ""),
                "tags": tags_norm((one(lg, "m-tags") or {}).get("text")),
                "workspaces": wss,
                "snapshots": [{"name": str(r.get("name")), "version": v12(r.get("version"))}
                              for r in rows(lg, "m-snaps")]}
        if str(F.get("tomb") or ""):
            body["tomb"] = str(F.get("tomb"))
        ok(S, body)
    if op == "summary":
        r = one(lg, "m-sum")
        if r is None:
            ok(S, {"version": v12(V), "level": str(S["args"].get("level") or "oneline"),
                   "pending": True})
        ok(S, {"version": v12(V), "level": str(S["args"].get("level") or "oneline"),
               "text": str(r.get("text") or ""), "model": str(r.get("model") or ""),
               "at": str(r.get("at") or "")})
    if op == "history":
        entries = []
        for r in history_rows(rows(lg, "m-line"), int(S.get("hist_limit") or 20)):
            e = {"at": str(r.get("at") or ""), "version": v12(r.get("version")),
                 "op": str(r.get("op") or "")}
            for k in ("prev", "note", "ws", "commit"):
                val = str(r.get(k) or "")
                if val:
                    e[k] = v12(val) if k == "prev" else val
            entries.append(e)
        ok(S, {"version": v12(V), "entries": entries})
    run = one(lg, "n-run")
    if run is not None and not run_whole(S, run, rows(lg, "n-rows")):
        # GH #947 (ledger 13): a run row that counts more rows than its
        # version holds -- a refused bundle left it behind -- is no answer: the
        # version is computed from its blocks, as without a run row, never
        # answered as a list that silently lacks its tail.
        run = None
    if run is not None:
        got = rows(lg, "n-rows")
        if op == "outline":
            nodes_answer(S, run, [node_of(r) for r in got])
        if op == "links":
            links_answer(S, [link_of(r) for r in got])
        if S["addr"].get("anchor"):
            span_of(S, [node_of(r) for r in got])
    # Content: every block of every wanted version, of THIS file only.
    hashes = []
    for v in sorted(set(wanted(S))):
        for h in loads(vrows[v].get("blocks"), []) or []:
            if str(h) not in hashes:
                hashes.append(str(h))
    S["vrows"] = {v: {"blocks": vrows[v].get("blocks"), "bytes": vrows[v].get("bytes"),
                      "lines": vrows[v].get("lines"), "parent": vrows[v].get("parent"),
                      "force": vrows[v].get("force"), "made_by": vrows[v].get("made_by"),
                      "at": vrows[v].get("at")}
                  for v in set(wanted(S))}
    fid = S["file_id"]
    ops = []
    for i in range(0, len(hashes), BLOCK_TRANCHE):
        chunk = hashes[i:i + BLOCK_TRANCHE]
        ops.append(("b-%d" % (i // BLOCK_TRANCHE), sel(
            "blocks", ["hash", "enc", "body"], {"file": fid, "hash": {"in": chunk}},
            None, len(chunk))))
    if op != "raw":
        vs = sorted(set(wanted(S)))
        ops.append(("d-parts", sel("derived", ["version", "part", "body"],
                                   {"file": fid, "version": {"in": vs}, "kind": "text"},
                                   [("part", "asc")], PARTS_MAX)))
    next_phase(S, "blocks", ops)


def run_whole(S, run, got):
    """Whether the rows read hold what the `node_runs` row counts: the select
    asked for `min(off + lim, cap) + 1` rows, so fewer than that and fewer
    than the run's count means rows of the version are missing."""
    if S["op"] == "links":
        off, lim = S["pg"]
        asked, have = min(off + lim, LINKS_MAX) + 1, int(run.get("links") or 0)
    else:
        off, lim = S.get("pg") or [0, NODES_MAX]
        asked, have = min(off + lim, NODES_MAX) + 1, int(run.get("nodes") or 0)
    return len(got) >= min(asked, have)


def nodes_answer(S, run, nodes):
    """`outline`: one page of the nodes; `run` the `node_runs` row or the
    `extract` result (parser, mark)."""
    off, lim = S["pg"]
    page, nxt = paged(nodes, off, lim)
    body = {"version": v12(S["V"]), "parser": str(run.get("parser") or "")}
    if str(run.get("mark") or ""):
        body["mark"] = str(run.get("mark"))
    body.update(nodes=page, next=nxt)
    ok(S, body)


def links_answer(S, links):
    off, lim = S["pg"]
    page, nxt = paged(links, off, lim)
    ok(S, {"version": v12(S["V"]), "links": page, "next": nxt})


def span_of(S, nodes):
    """`read` of `fh-...#<anchor>`: the node goes on to the content read, an
    unknown anchor answers `unknown_anchor` with candidates of its name."""
    anchor = S["addr"]["anchor"]
    node, cands = node_at(nodes, anchor)
    if node is None:
        fail(S, "unknown_anchor", "this version has no node %s" % anchor,
             extra={"candidates": cands})
    S["node"] = {"anchor": node["anchor"], "unit": node["unit"], "from": node["from"],
                 "to": node["to"]}


def view_of(S, lg, v, blocks_rows):
    content = assemble(S["vrows"][v], blocks_rows)
    if content is None:
        fail(S, "corrupt", "a block of this version is missing")
    parts = [{"part": r.get("part"), "text": r.get("body")}
             for r in rows(lg, "d-parts") if str(r.get("version")) == v]
    return content, text_view(content, parts)


def on_blocks(S, lg):
    op, V, a = S["op"], S["V"], S["args"]
    blocks_rows = []
    for cid in sorted(lg):
        if cid.startswith("b-"):
            blocks_rows.extend(rows(lg, cid))
    if op in NODE_OPS or (S["addr"].get("anchor") and not S.get("node")):
        v = wanted(S)[0]
        content = assemble(S["vrows"][v], blocks_rows)
        if content is None:
            fail(S, "corrupt", "a block of this version is missing")
        parts = [{"part": r.get("part"), "text": r.get("body")}
                 for r in rows(lg, "d-parts") if str(r.get("version")) == v]
        frow = S["frow"]
        ex = extract(str(frow.get("path") or ""), str(frow.get("mime") or ""), content,
                     parts or None, LIMITS)
        nodes = sorted((node_of(n) for n in ex["nodes"]), key=node_key)
        if op == "outline":
            nodes_answer(S, ex, nodes)
        if op == "links":
            links_answer(S, sorted((link_of(l) for l in ex["links"]), key=link_key))
        span_of(S, nodes)
    if op == "raw":
        v = wanted(S)[0]
        content = assemble(S["vrows"][v], blocks_rows)
        if content is None:
            fail(S, "corrupt", "a block of this version is missing")
        ok(S, {"version": v12(v), "mime": str(S["frow"].get("mime") or ""),
               "bytes": len(content), "b64": base64.b64encode(content).decode("ascii")})
    if op == "diff":
        va, vb = wanted(S)
        _, ta = view_of(S, lg, va, blocks_rows)
        _, tb = view_of(S, lg, vb, blocks_rows)
        if "error" in ta or "error" in tb:
            fail(S, "no_text", "this version has no text view")
        fid = S["file_id"]
        text, cut = unified(ta["lines"], tb["lines"], "%s@%s" % (fid, v12(va)),
                            "%s@%s" % (fid, v12(vb)))
        body = {"version": v12(V), "a": v12(va), "b": v12(vb), "diff": text}
        if cut:
            body["truncated"] = True
        ok(S, body)
    v = wanted(S)[0]
    _, tv = view_of(S, lg, v, blocks_rows)
    if "error" in tv:
        fail(S, "no_text", "this version has no text view")
    lines = tv["lines"]
    if op == "show":
        VR = S["vrows"][v]
        body = {"version": v12(v), "bytes": int(VR.get("bytes") or 0),
                "lines": int(VR.get("lines") or 0), "at": str(VR.get("at") or ""),
                "made_by": str(VR.get("made_by") or ""),
                "head": window(lines, 1, min(len(lines), SHOW_LINES))[0]}
        if str(VR.get("parent") or ""):
            body["parent"] = v12(VR.get("parent"))
        if str(VR.get("force") or "") not in ("", "0"):
            body["force"] = True
        ok(S, body)
    if op == "search":
        pattern = str(a.get("pattern") or "")
        mode = str(a.get("mode") or "exact")
        if not pattern or len(pattern) > PATTERN_MAX:
            fail(S, "bad_pattern", "a pattern is 1 to %d characters" % PATTERN_MAX)
        if mode not in ("exact", "regex"):
            fail(S, "bad_request", "mode is exact or regex here")
        if mode == "regex":
            try:
                re.compile(pattern)
            except re.error as e:
                fail(S, "bad_pattern", "not a regular expression: %s" % e)
        context = min(CONTEXT_MAX, max(0, int(a.get("context") or 0)))
        limit = min(SEARCH_LIMIT, max(1, int(a.get("limit") or SEARCH_LIMIT)))
        hits, total, cut = search_lines(lines, pattern, mode, context, limit)
        body = {"version": v12(V), "hits": hits, "total": total}
        if cut:
            body["more"] = True
        ok(S, body)
    # read
    total = len(lines)
    body = {"version": v12(V), "lines": total}
    node = S.get("node")
    if node and node["unit"] == "page":
        n = int(node["from"])
        if n not in tv["pages"]:
            fail(S, "page_unknown", "this version has no page %d" % n)
        text, first, last, more = window(lines, *tv["pages"][n])
        body.update(anchor=node["anchor"], page=n, pages=len(tv["pages"]))
    elif node:
        # A node's lines, the same form as a read by range; past the end
        # (a node of other text than this view) it is cut at the last line.
        fa, fb = max(1, int(node["from"])), min(total, int(node["to"]))
        if fa > fb:
            fail(S, "bad_range", "the node holds no line of %d" % total)
        text, first, last, more = window(lines, fa, fb)
        body["anchor"] = node["anchor"]
    elif a.get("page") not in (None, "") and not page_ignored(a, tv):
        n = int(a.get("page"))
        if n not in tv["pages"]:
            fail(S, "page_unknown", "this version has no page %d" % n)
        pa, pb = tv["pages"][n]
        text, first, last, more = window(lines, pa, pb)
        body.update(page=n, pages=len(tv["pages"]))
    else:
        if a.get("page") not in (None, ""):
            body["ignored"] = ["page"]
        if total == 0:
            ok(S, dict(body, text=""))
        try:
            fa, fb = span(a, total)
        except (TypeError, ValueError):
            fail(S, "bad_request", "from and to are line numbers")
        if fa > fb:
            fail(S, "bad_range", "the range holds no line of %d" % total)
        text, first, last, more = window(lines, fa, fb)
    body.update({"from": first, "to": last, "text": text})
    if more:
        body["more"] = more
    ok(S, body)


def on_near(S, lg):
    """The own file vector against the scanned ones; the live files among the
    candidates are asked for next (their paths break a tie)."""
    mine = str((one(lg, "n-mine") or {}).get("fvec") or "")
    dist = {}
    if mine:
        for r in rows(lg, "n-scan"):
            f = str(r.get("file") or "")
            if not f or f == S["file_id"] or f in dist:
                continue
            d = hamming_b64(mine, r.get("fvec"))
            if d is not None:
                dist[f] = d
    if not dist:
        ok(S, {"near": []})
    S["near"] = {"bits": 8 * len(base64.b64decode(mine)), "dist": dist}
    files = sorted(dist)
    ops = []
    for i in range(0, len(files), BLOCK_TRANCHE):
        chunk = files[i:i + BLOCK_TRANCHE]
        ops.append(("n-f-%d" % (i // BLOCK_TRANCHE), sel(
            "files", ["file", "path"], {"file": {"in": chunk}, "tomb": "", "head": {"neq": ""}},
            None, len(chunk))))
    next_phase(S, "near_files", ops)


def on_near_files(S, lg):
    N = S["near"]
    paths = {}
    for cid in sorted(lg):
        if cid.startswith("n-f-"):
            for r in rows(lg, cid):
                paths[str(r.get("file") or "")] = str(r.get("path") or "")
    ok(S, {"near": near_of(N["dist"], paths, int(S["k"]), N["bits"])})


# ============================================================ LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
op_ = str(hop.get("operation") or "")

if lane == "in_read":
    op = str(hop.get("op") or d.get("op") or "")
    S = {"op": op, "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
         "args": d.get("args") if isinstance(d.get("args"), dict) else {}}
    if not S["op_id"]:
        fail(S, "bad_request", "a request carries hop.op_id", parked=False)
    if op not in OPS:
        fail(S, "unknown_op", "this lane serves " + ", ".join(OPS), parked=False)
    ws_name = str(hop.get("ws") or "")
    if ws_name and not NAME_RE.match(ws_name):
        fail(S, "bad_request", "a workspace name is 1 to 64 of [A-Za-z0-9._-]", parked=False)
    if op not in SPACE_OPS:
        raw = d.get("file")
        at = S["args"].get("at")
        if at not in (None, "") and isinstance(raw, str) and "@" not in raw:
            raw = raw + "@" + str(at)
        addr = parse_addr(raw)
        if "error" in addr:
            fail(S, addr["error"], "an address is fh-<12 hex> or /path, with @<hex>, "
                 "@ws:<name> or @snap:<name>", parked=False)
        if addr["anchor"] and op != "read":
            # A node is read by `read`; every other op here answers for a
            # whole file (a node is written by `./write`: `write_node`, and
            # `insert` at an anchor, GH #947).
            fail(S, "anchor_unsupported", "only read takes an anchor", parked=False)
        if addr["at"] == "ws":
            ws_name = addr["ref"]
        S["addr"] = addr
    S["ws_name"] = ws_name
    if op == "near" and (S["addr"]["at"] != "head" or ws_name):
        # `near` compares heads: the one file vector a file has is its
        # head's (`node_runs` holds the head only).
        fail(S, "bad_request", "near compares heads: no version, workspace or snapshot",
             parked=False)
    bad_args = node_args(S)
    if bad_args:
        fail(S, "bad_request", bad_args, parked=False)
    start(S)

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op_:
    park("a message with neither a lane nor a store answer -- dropped")
if phase == "done":
    emit([])

lg = legs(d)
echo = one(lg, "p-echo")
parked = loads((echo or {}).get("body"), None)
if not isinstance(parked, dict):
    park("store answer in phase %r without its parked request -- dropped" % phase)
bad = sorted(cid for cid, leg in lg.items() if leg["error_code"])
if bad:
    sys.stderr.write("file-space/read: store refused %s in phase %s\n" % (", ".join(bad), phase))
    fail(parked, "store_error", "the store refused a read; try again later")

if phase == "file":
    on_file(parked, lg)
if phase == "version":
    on_version(parked, lg)
if phase == "meta":
    on_meta(parked, lg)
if phase == "blocks":
    on_blocks(parked, lg)
if phase == "list":
    on_list(parked, lg)
if phase == "dir":
    on_dir(parked, lg)
if phase == "find":
    on_find(parked, lg)
if phase == "near":
    on_near(parked, lg)
if phase == "near_files":
    on_near_files(parked, lg)
park("unknown phase %r -- dropped" % phase)
